# 41d_staffing_figure.R
# Mean staffing spend per MP, real terms — full series 1979 to 2023-24
#
# DATA:
#   data/processed/ipsa_staffing_annual.csv     — IPSA actual (2011-12 to 2023-24)
#   data/raw/staffing_pre2010_modelled.csv      — pre-2010 modelled estimates
#     Method: HC allowance maxima (HC Annual Reports) × 85% utilisation rate
#     PLACEHOLDER — to be calibrated against Butler & Butler (2011) on 30 Apr 2026
#
# OUTPUT: figures/ch3_staffing_chow_talk.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, readr, patchwork)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT  <- .ROOT
IPSA_IN   <- file.path(PROJECT, "data/processed/ipsa_staffing_annual.csv")
PRE10_IN  <- file.path(PROJECT, "data/raw/staffing_pre2010_modelled.csv")
TALK_OUT  <- file.path(PROJECT, "figures/ch3_staffing_chow_talk.png")

NAVY      <- "#1F3864"
RED       <- "#d7191c"
GREY_BLUE <- "#607D8B"
LIGHT_BLUE <- "#a6bddb"   # pre-2010 modelled estimates

# ============================================================
# 1. LOAD AND COMBINE
# ============================================================
ipsa  <- read_csv(IPSA_IN,  show_col_types = FALSE) |>
  mutate(is_modelled = FALSE)

pre10 <- read_csv(PRE10_IN, show_col_types = FALSE) |>
  select(financial_year, cal_year, n_mps,
         mean_staffing_nominal, mean_staffing_real_2015,
         election_year_filter, is_modelled)

d <- bind_rows(pre10, ipsa) |>
  arrange(cal_year) |>
  mutate(
    t          = cal_year - min(cal_year),
    elec_dummy = as.integer(election_year_filter),
    bar_type   = case_when(
      is_modelled                         ~ "Pre-2010 (modelled)",
      !is_modelled & election_year_filter ~ "IPSA actual — election yr",
      TRUE                                ~ "IPSA actual"
    ),
    bar_type       = factor(bar_type,
                            levels = c("IPSA actual", "IPSA actual — election yr",
                                       "Pre-2010 (modelled)")),
    financial_year = factor(financial_year, levels = financial_year)  # preserve cal_year order
  )

cat(sprintf("Combined series: %d observations (%d modelled, %d IPSA actual)\n",
            nrow(d), sum(d$is_modelled), sum(!d$is_modelled)))

# ============================================================
# 2. PANEL A — bar chart
# ============================================================
p_series <- ggplot(d, aes(x = financial_year, y = mean_staffing_real_2015 / 1000,
                           fill = bar_type)) +
  geom_col(width = 0.75) +
  scale_fill_manual(
    values = c(
      "IPSA actual"              = NAVY,
      "IPSA actual — election yr" = GREY_BLUE,
      "Pre-2010 (modelled)"      = LIGHT_BLUE
    ),
    name = NULL
  ) +
  scale_x_discrete(drop = FALSE) +
  scale_y_continuous(
    labels = function(x) paste0("£", x, "k"),
    expand = expansion(mult = c(0, 0.08))
  ) +
  labs(
    title    = "A. Mean staffing spend per MP, real terms (2015 prices), 1978–79 to 2023–24",
    subtitle = paste0(
      "Light blue bars = modelled estimates (HC allowance max × 85% utilisation) — PLACEHOLDER pending Butler & Butler (2011) calibration.\n",
      "IPSA actual from 2011-12; election years filtered to MPs with ≥£50k spend. 2024-25 excluded (July GE distortion)."
    ),
    x = NULL,
    y = "Mean staffing spend per MP (£000, 2015 prices)"
  ) +
  theme_bw(base_size = 11) +
  theme(
    plot.title         = element_text(face = "bold", colour = NAVY, size = 11),
    plot.subtitle      = element_text(colour = "#888888", size = 7.5, lineheight = 1.2),
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank(),
    axis.text.x        = element_text(angle = 45, hjust = 1, size = 9),
    legend.position    = "top",
    legend.text        = element_text(size = 8)
  )

# ============================================================
# 3. CHOW STRUCTURAL BREAK (all observations)
# ============================================================
n_chow <- nrow(d)
p_reg  <- 2   # intercept + slope (election dummy always included)

mod_r <- lm(mean_staffing_real_2015 ~ t + elec_dummy, data = d)
RSS_r <- sum(resid(mod_r)^2)

years_sorted     <- sort(d$cal_year)
candidate_breaks <- years_sorted[3:(length(years_sorted) - 3)]

chow_results <- do.call(rbind, lapply(candidate_breaks, function(k) {
  dat1 <- d |> filter(cal_year <= k)
  dat2 <- d |> filter(cal_year >  k)
  if (nrow(dat1) < 3 || nrow(dat2) < 3) return(NULL)
  rss1 <- tryCatch(
    sum(resid(lm(mean_staffing_real_2015 ~ t + elec_dummy, data = dat1))^2),
    error = function(e) NA)
  rss2 <- tryCatch(
    sum(resid(lm(mean_staffing_real_2015 ~ t + elec_dummy, data = dat2))^2),
    error = function(e) NA)
  if (is.na(rss1) || is.na(rss2)) return(NULL)
  RSS_u  <- rss1 + rss2
  F_stat <- ((RSS_r - RSS_u) / p_reg) / (RSS_u / (n_chow - 2 * p_reg - 1))
  data.frame(break_year = k, F_stat = max(F_stat, 0),
             n1 = nrow(dat1), n2 = nrow(dat2))
}))

F_crit     <- qf(0.95, df1 = p_reg, df2 = n_chow - 2 * p_reg - 1)
best_break <- chow_results$break_year[which.max(chow_results$F_stat)]
best_F     <- max(chow_results$F_stat)

cat(sprintf("Chow: N=%d, critical F(%d,%d)=%.2f\n",
            n_chow, p_reg, n_chow - 2*p_reg - 1, F_crit))
cat(sprintf("Data-preferred break: %d (F=%.2f)\n", best_break, best_F))
print(chow_results)

# ============================================================
# 4. PANEL B — Chow F
# ============================================================
p_chow <- ggplot(chow_results, aes(x = factor(break_year), y = F_stat)) +
  geom_col(fill = NAVY, width = 0.7) +
  geom_hline(yintercept = F_crit, linetype = "dashed",
             colour = RED, linewidth = 0.7) +
  annotate("text",
           x     = as.character(candidate_breaks[length(candidate_breaks)]),
           y     = F_crit + max(chow_results$F_stat) * 0.05,
           label = sprintf("Critical F(%d,%d) = %.2f (5%%)", p_reg,
                           n_chow - 2*p_reg - 1, F_crit),
           hjust = 1, size = 2.5, colour = RED) +
  annotate("text",
           x     = as.character(best_break),
           y     = best_F + max(chow_results$F_stat) * 0.05,
           label = paste0("Peak:\n", best_break),
           hjust = 0.5, size = 2.5, colour = NAVY) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
  labs(
    title    = "B. Chow structural break test (election-year-controlled)",
    subtitle = sprintf(
      paste0("Model: real staffing spend ~ time + election_dummy. N=%d (%d modelled pre-2010).\n",
             "Data-preferred break: %d (F=%.2f). Critical value: %.2f.\n",
             "Note: pre-2010 bars are modelled estimates — Chow will update after Butler & Butler calibration."),
      n_chow, sum(d$is_modelled), best_break, best_F, F_crit),
    x = "Candidate break year", y = "Chow F-statistic"
  ) +
  theme_bw(base_size = 11) +
  theme(
    plot.title         = element_text(face = "bold", colour = NAVY, size = 11),
    plot.subtitle      = element_text(colour = "#888888", size = 7.5, lineheight = 1.2),
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank(),
    axis.text.x        = element_text(angle = 45, hjust = 1)
  )

# ============================================================
# 5. COMBINE AND SAVE
# ============================================================
p_talk <- p_series / p_chow +
  plot_layout(heights = c(2, 1)) +
  plot_annotation(
    caption = paste0(
      "Sources: IPSA Annual Total Spend 2011-12 to 2023-24 (theipsa.org.uk); pre-2010 bars = modelled estimates ",
      "(HC allowance max × 85% utilisation, ONS CPI 2015=100).\n",
      "Pre-2010 estimates to be calibrated against Butler & Butler (2011) British Political Facts, HC Members' Allowances tables. ",
      "Election years filtered (≥£50k staffing spend)."
    ),
    theme = theme(plot.caption = element_text(size = 6.5, colour = "#888888",
                                              lineheight = 1.2))
  )

ggsave(TALK_OUT, p_talk, width = 10, height = 9, dpi = 300)
cat("Talk figure saved:", TALK_OUT, "\n")
